	 async function waitForCarousel() {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject('Timeout: flickity-carousel no encontrado'), 5000);

      const check = () => {
        const carousel = document.querySelector('flickity-carousel');
        if (carousel && carousel.flickityInstance) {
          clearTimeout(timeout);
          carousel.flickityInstance.then(resolve);
        } else {
          setTimeout(check, 100);
        }
      };
      check();
    });
  }


  async function addImageToCarousel(imageUrl, imageAlt = '', position = null) {
  const carousel = document.querySelector('flickity-carousel');
  if (!carousel) return console.error('No se encontró flickity-carousel');

  // ID único compartido entre slide y thumbnail
  const slideId = `product-test-${Date.now()}`;

  // --- SLIDE ---
  const slide = document.createElement('div');
  slide.id = slideId;
  slide.className = 'product__media-item';
  slide.setAttribute('data-media-id', slideId);

  const imageWrapper = document.createElement('div');
  imageWrapper.className = 'product__media-image-wrapper aspect-ratio aspect-ratio--natural';

  const img = document.createElement('img');
  img.src = imageUrl;
  img.alt = imageAlt;
  img.loading = 'eager';
  img.sizes = '(max-width: 999px) calc(100vw - 48px), 640px';

  imageWrapper.appendChild(img);
  slide.appendChild(imageWrapper);

  // --- THUMBNAIL ---
  const thumbnail = document.createElement('button');
  thumbnail.type = 'button';
  thumbnail.tabIndex = -1;
  thumbnail.className = 'product__thumbnail-item';
  thumbnail.setAttribute('aria-controls', slideId); // conecta con el slide
  thumbnail.setAttribute('data-media-id', slideId);
  thumbnail.setAttribute('data-action', 'select');   // flickity-controls escucha esto

  const thumbnailInner = document.createElement('div');
  thumbnailInner.className = 'product__thumbnail';

  const thumbImg = document.createElement('img');
  thumbImg.src = imageUrl;
  thumbImg.alt = imageAlt;
  thumbImg.loading = 'lazy';
  thumbImg.sizes = '(max-width: 999px) 72px, 60px';

  thumbnailInner.appendChild(thumbImg);
  thumbnail.appendChild(thumbnailInner);

  // Insertar thumbnail en la lista
  const thumbnailList = document.querySelector('.product__thumbnail-list-inner');
  if (thumbnailList) {
    if (position !== null) {
      thumbnailList.insertBefore(thumbnail, thumbnailList.children[position]);
    } else {
      thumbnailList.appendChild(thumbnail);
    }
  }
	// --- DOT ---
  const dotsNav = document.querySelector('.dots-nav');
  if (dotsNav) {
    const dot = document.createElement('button');
    dot.type = 'button';
    dot.tabIndex = -1;
    dot.className = 'dots-nav__item tap-area';
    dot.setAttribute('aria-controls', slideId);
    dot.setAttribute('data-media-id', slideId);
    dot.setAttribute('data-action', 'select');
    dot.innerHTML = '<span class="visually-hidden">Go to slide</span>';

    if (position !== null) {
      dotsNav.insertBefore(dot, dotsNav.children[position]);
    } else {
      dotsNav.appendChild(dot);
    }
  }
  // Insertar slide en flickity
  const flickity = await carousel.flickityInstance;
  if (position !== null) {
    flickity.insert(slide, position);
  } else {
    flickity.append(slide);
  }

  img.onload = function () {
  const ratio = img.naturalWidth / img.naturalHeight;
  imageWrapper.style.paddingBottom = (100 / ratio) + '%';
  imageWrapper.style.setProperty('--aspect-ratio', ratio);
  flickity.resize();
  flickity.reloadCells();
};
